func (u *UserConfig) validate() error {
    var errMsgs []string
    if u.MaxConnections < MinmumMaxConnections { errMsgs = append(errMsgs, ... "maxConnections must be a positive integer with a minimum of %d" ...) }
    if u.MaxConnections > MaximumMaxConnections { ... }
    if u.EFConstruction < MinmumEFConstruction { ... "efConstruction must be a positive integer ..." }
    if u.FilterStrategy != FilterStrategySweeping && u.FilterStrategy != FilterStrategyAcorn { ... }
    if len(errMsgs) > 0 { return fmt.Errorf("invalid hnsw config: %s", ...) }
}
